#!/usr/bin/env bash
# Offline test of coverage-gate.sh on a fake repository and coverage profile.
# Usage: scripts/coverage-gate_test.sh
set -euo pipefail

here="$(cd "$(dirname "$0")" && pwd)"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT

mod="example.test/m"
fail=0

# new_repo makes $tmp/repo with a copy of the gate and one hand-written file
# (covered) and one generated file (not covered).
new_repo() {
	rm -rf "$tmp/repo"
	mkdir -p "$tmp/repo/scripts" "$tmp/repo/internal/a"
	cp "$here/coverage-gate.sh" "$tmp/repo/scripts/"
	printf 'module %s\n\ngo 1.21\n' "$mod" >"$tmp/repo/go.mod"
	printf 'package a\n' >"$tmp/repo/internal/a/a.go"
	printf '// Code generated by tool v1 DO NOT EDIT.\n\npackage a\n' >"$tmp/repo/internal/a/x.gen.go"
	cat >"$tmp/repo/coverage.out" <<EOF
mode: atomic
$mod/internal/a/a.go:1.1,2.2 10 1
$mod/internal/a/x.gen.go:1.1,2.2 90 0
EOF
}

# expect NAME WANT-EXIT [args...] runs the gate from $PWD.
expect() {
	local name="$1" want="$2" got=0
	shift 2
	"$tmp/repo/scripts/coverage-gate.sh" "$@" >"$tmp/out" 2>&1 || got=$?
	if [[ "$got" != "$want" ]]; then
		echo "FAIL $name: exit $got, want $want"
		cat "$tmp/out"
		fail=1
	else
		echo "ok   $name"
	fi
}

new_repo
(cd "$tmp/repo" && expect "generated file with header is excluded" 0 coverage.out 80)

new_repo
(cd "$tmp/repo" && expect "threshold still applies" 1 coverage.out 101)

new_repo
printf 'package a\n' >"$tmp/repo/internal/a/y.gen.go"
(cd "$tmp/repo" && expect "gen.go file without the header fails" 2 coverage.out 80)
grep -q "lacks the" "$tmp/out" || { echo "FAIL: no clear message"; fail=1; }

new_repo
(cd "$tmp" && expect "runs from another directory, relative profile" 0 repo/coverage.out 80)

new_repo
sed -i 's|^// Code generated.*|// Code generated by tool v1 DO NOT EDIT. trailing|' "$tmp/repo/internal/a/x.gen.go"
(cd "$tmp/repo" && expect "header must end with DO NOT EDIT." 2 coverage.out 80)

exit "$fail"
